const imageFor={midnight:'/images/castle.jpg',sea:'/images/sea.jpg',orchard:'/images/forest.jpg',europa:'/images/space.jpg',names:'/images/city.jpg',ember:'/images/desert.jpg'};
function build(key,title,genre,description,settings,cast,chapters,decisions){
 const id='library-'+key;
 const edges=[[2,3],[4],[4],[5],[6],[7,8],[9],[10],[],[]];
 return {id,contentId:key,libraryVersion:1,complete:true,title,genre,description,cover:imageFor[key],characterIds:cast.map(c=>c.id),locationIds:settings.map(l=>l.id),scenes:chapters.map((c,i)=>({id:i+1,title:c[0],text:c[2],location:settings[c[1]].name,image:settings[c[1]].image,thread:['discovery','identity','magic'][i%3],status:'Ready for review',tag:i<3?'Act I':i<6?'Act II':i<8?'Act III':'Resolution',choices:edges[i].map((target,j)=>({label:decisions[i]?.[j]||'Continue to '+chapters[target-1][0].toLowerCase(),target}))})),cast:cast.map(c=>({...c,projectId:id,projectTitle:title,color:c.color||'#b9a5df',image:c.image||null,referenceReady:!!c.image,archetype:c.archetype||c.role,prompt:c.prompt||`Character development brief for ${c.name}, ${c.age}. ${c.description} Motivation: ${c.desire} Central conflict: ${c.conflict} Create a consistent, naturalistic live-action identity, credible physical features, culturally grounded clothing, and a four-angle full-body reference. Maintain the same age, proportions, hair, and costume across front, profile, three-quarter, and back views. Realistic skin pores and fabric textures. No text, watermark, celebrity likeness, or inconsistent accessories.`})),settings:settings.map(l=>({...l,projectId:id,projectTitle:title}))};
}
function place(id,name,type,image,description,atmosphere,detail){return{id,name,type,image,description,atmosphere,detail};}

const midnightSettings=[
place('midnight-quarter','The Old Quarter','Inciting setting','/images/city.jpg','A district built around an abandoned tram loop. Elara repairs instruments above a shuttered music shop. At midnight, the copper gutters ring in a wind that never reaches the street. The room’s narrow window, an inherited kettle, and a repaired violin case establish the ordinary life she risks losing.','Rain-washed · Intimate · Uneasy','Interior / Exterior · Midnight'),
place('midnight-castle','Ashford Castle','Primary setting','/images/castle.jpg','A functioning school and archive above a valley that appears on no public map. The east tower holds a machine that removes dangerous memories and, increasingly, harmless ones. Changes in the castle’s doors follow changes in what its residents are allowed to remember.','Beautiful · Institutional · Untrustworthy','Interior / Exterior · Dawn & night'),
place('midnight-library','The Restricted Library','Revelation chamber','/images/library.jpg','An archive beneath the school. Shelf labels name people rather than subjects. A shallow brass bowl holds water that reflects the last truthful thing said nearby. Maeve records every removed memory here, including evidence of her own complicity.','Quiet · Confessional · Forbidden','Interior · Night'),
place('midnight-wood','The Whispering Wood','Escape route','/images/forest.jpg','A forest of white-barked trees beyond the northern gate. Names spoken here return as echoes from different directions. A root bridge crosses the river to the village; it remains visible only to people who admit what they are afraid of.','Living · Disorienting · Protective','Exterior · Predawn')];
const midnightCast=[
{id:'elara',name:'Elara Voss',age:24,role:'Protagonist',archetype:'The reluctant explorer',image:'/images/elara.png',description:'An instrument repairer raised by a grandmother who refused to discuss her parents. Elara notices changes in pitch before changes in language. She mistakes self-reliance for safety and initially treats every invitation as a debt. At Ashford she discovers that her mother designed the memory engine, and that the gaps in her childhood were deliberately made.',desire:'Recover the truth about her mother without surrendering the ordinary life she built.',conflict:'She wants an uncontaminated memory of the past, but the truth includes people she has grown to trust.'},
{id:'rowan',name:'Rowan Ashford',age:28,role:'Ally',archetype:'The guarded guide',image:'/images/rowan.png',description:'A former student employed as the castle’s night porter. Rowan keeps handwritten route maps because doors vanish from his memory after each inspection. He helped Elara’s mother escape years ago but accepted a removal procedure to avoid prosecution. His easy competence hides an increasingly frightening inability to recognise familiar faces.',desire:'Keep Elara out of the engine room until he can retrieve the evidence that will protect her.',conflict:'Every protective lie resembles the institution’s own justification for erasing people.'},
{id:'maeve',name:'Maeve Thorne',age:58,role:'Mentor',archetype:'The compromised archivist',image:'/images/maeve.png',description:'Keeper of the restricted archive and the last person to see Elara’s mother before her disappearance. Maeve preserved forbidden records but signed the orders that removed the memories themselves. She has spent seventeen years confusing documentation with resistance. Her arc requires public responsibility rather than a private act of kindness.',desire:'Release the memory archive while preventing a violent collapse of the school.',conflict:'To become a trustworthy witness, she must admit that she was also an administrator of the harm.'},
{id:'orren-vale',name:'Orren Vale',age:46,role:'Antagonist',description:'The school’s elegant director. A childhood disaster convinced him that grief makes people dangerous. He now measures peace by the absence of complaint. Orren speaks gently, never threatens without offering comfort, and sees Elara as a technical solution rather than an enemy. He is most dangerous when he is sincerely compassionate.',desire:'Make the engine permanent before its damage becomes public.',conflict:'He cannot distinguish caring for people from deciding which parts of them are permitted to exist.'}];
const midnightChapters=[
['The letter that found you',0,`The letter arrived while Elara was tuning a cracked violin. It floated through the closed window and settled beside her grandmother’s kettle, leaving no water on the sill. The emerald seal carried the same seven-pointed mark Elara had found scratched beneath the violin’s bridge. Someone had written her full name, including the middle name nobody outside the family knew.

Inside was an invitation to Ashford Castle and a second, hurried sentence: If they offer to help you forget, ask what they need you to remember. A small photograph slipped from the fold. Elara recognised herself at seven, standing beside a woman whose face had been cut out. The cut edges were worn smooth by repeated handling.

An owl tapped the glass. On the street below, a tram with no driver stopped at the abandoned loop. Elara put the violin in its case. She could inspect the tram’s silver route map, or follow the owl towards the rooftops.`],
['The station beneath the street',0,`The tram descended a ramp that should have ended in the canal. Instead it entered a tiled station smelling of wet copper. Rowan waited on the platform with a lantern and two tickets. He looked at the photograph before he looked at Elara.

“Your mother always kept the damaged copy,” he said, then winced as if the sentence had escaped a locked room. He could not answer where he had met her. His pocket notebook contained a map of the castle and a reminder in his own handwriting: Do not let them call absence recovery.

He offered Elara a spare ticket with the date printed seventeen years earlier. She matched the seven-pointed mark to the back of her photograph. Rowan was frightened of the castle, but someone there had once trusted him with a child. She followed him onto a carriage whose windows reflected a sunrise the city had not yet seen.`],
['A path made of names',3,`The owl led Elara across the roofs to an iron stair hidden inside a bell tower. Beyond its top step, the city was gone. White-barked trees stood around a river, and every branch carried a paper tag. Elara read one and heard her grandmother’s laugh in the dark.

She reached for another. A woman’s voice said her name exactly as it had sounded in childhood. The memory was brief: warm hands, a blue work apron, a promise to return before the kettle boiled. Elara sat down on the wet ground, suddenly furious at how small the recovered moment was.

Rowan appeared on the far bank, following a map he had drawn that morning and forgotten drawing. He did not try to explain her tears. He showed her the root bridge and admitted he was afraid of forgetting her again. When Elara said she feared discovering that her mother had chosen to leave, the bridge became visible. They crossed together.`],
['A welcome with missing pieces',1,`Ashford’s dining hall was bright with candles and the comforting noise of ordinary students. Director Orren Vale welcomed Elara as an honoured guest. He described her mother as a brilliant engineer who had suffered a breakdown and disappeared. Then he offered a treatment for the distress of uncertain memories.

Elara asked what he needed her to remember. A spoon stopped halfway to Maeve Thorne’s mouth. Orren smiled without answering and changed the subject to the east tower, where an old engine required a particular kind of hearing to repair.

Later, Rowan showed Elara three doors on his map. There were only two in the corridor. Behind the blank wall she heard a low note, precisely the pitch of the repaired violin. Maeve stepped out of the surviving doorway carrying a bowl of water. “Your mother did not break down,” she said. “But I helped them make that the story. Come downstairs before I lose the courage to tell you the rest.”`],
['The archive of surrendered things',2,`The restricted shelves held memories in thin glass cylinders. A label might read First swimming lesson, or The argument before the wedding. Elara found entire drawers marked Civic stability. Many removals had no signed consent.

Maeve placed the bowl beneath a lamp and confessed that Elara’s mother had built the engine to quiet traumatic flashbacks, never to erase their causes. Orren had expanded it until even disagreement could be treated as illness. When the engineer objected, Maeve signed the order that removed her identity from the school’s records. Rowan had carried seven-year-old Elara out through the forest.

There was no cylinder containing her mother’s death. There was instead a transfer record to a village across the river. Her mother was alive, living without the memories that would tell her whom to seek. Elara demanded that Maeve open the archive. Maeve handed over her seal and the original removal orders. “Take the evidence too,” she said. “Do not let helping you become the end of my responsibility.”`],
['The engine that learned to hunger',1,`In the east tower, Elara heard the engine’s fault before she saw it. Its seven resonators no longer balanced. Each attempt to suppress one memory stripped nearby memories from the same person. The school was becoming a place where people could recite facts but no longer remember caring about them.

Orren arrived with a guard and a glass cylinder containing a recovered moment from Elara’s childhood. He offered to restore her mother completely if she stabilised the machine. Elara saw how carefully he had chosen a reward that made everyone else’s suffering seem negotiable.

Rowan opened the tower windows. Maeve’s copied orders were already moving through the school in students’ hands. Orren could no longer keep the engine secret, but stopping it would be dangerous. Elara identified two defensible choices: release all the stored memories through the resonators, accepting a wave of uncontrolled grief, or isolate the engine and return memories one person at a time under independent supervision.`],
['Every window open',1,`Elara struck the first resonator with the violin’s bow. Its note travelled through the castle, and the cylinders in the archive began to sing. Rowan held the window mechanism while students tied the shutters open. Maeve read the names on the removal orders over the hall’s speaking tubes, refusing to let the returning memories become anonymous pain.

Orren tried to close the last shutter. Rowan stopped him, not with a blow but by asking him to listen. From the courtyard came recognition: a father’s name, a lost language, the reason two old friends had stopped speaking. There was anger too, and people who needed quiet rooms and company before they could stand.

The overload cracked a resonator. Elara caught the falling glass in her coat and lost the small memory of her first music lesson. The cost was real and immediate. She kept playing until the engine fell silent. When she lowered the bow, Rowan remembered the child he had carried to safety.`],
['A lock nobody owns alone',1,`Elara shut the intake valves rather than breaking the resonators. The silence frightened her more than their noise had. Every stored memory remained inside, and Orren immediately proposed an emergency committee chaired by himself.

Maeve placed her seal on the floor and broke it with a hammer. She insisted on a group including students, former patients, the village physician, and people who had refused treatment. Elara separated the engine into seven circuits. No single key could restart it. Rowan delivered the first cylinders to the people named on their labels and stayed while each decided whether to open them.

Restoration would take months. Some refused. Some wanted a witness before they remembered. Elara accepted a limit she would once have found unbearable: rescuing her mother did not give her the right to decide what her mother should recover. Orren was removed from the tower by the very guard who had been told his own nightmares were misconduct.`],
['The tune on the other bank',3,`The village physician warned Elara that restored memories did not return in a useful order. Her mother might remember a corridor before a daughter. Elara crossed the root bridge carrying the violin, prepared to introduce herself without demanding recognition.

Her mother was repairing a kettle in a kitchen overlooking the river. She looked older than the cut photograph and entirely real. Elara played the tune she had used to stop the engine. Halfway through, her mother took over the rhythm by tapping a spoon against the workbench. “You used to rush that part,” she said.

They did not recover seventeen years in an afternoon. They made tea and started with the names of people who had helped them. At Ashford, a public inquiry opened the archive and arranged care for those hurt by the release. Maeve testified without asking forgiveness. Elara returned to her shop with her mother’s address in her pocket. The next letter came through the ordinary post, and this time nothing had been cut out.`],
['The right to begin again',2,`Three months later, the archive opened as a clinic with public records and a door that never locked from the outside. Every restoration required a request, a witness chosen by the patient, and the right to stop. Maeve worked there under supervision while giving evidence at the inquiry. Rowan’s notebooks grew thinner as he recovered the reasons behind his maps.

Elara visited her mother each Sunday. Some memories returned; others did not. When her mother asked whether she should try the childhood cylinder, Elara said the decision was hers and meant it. They built a new memory instead: a repaired violin, two cups of tea, and an argument about the right amount of sugar.

Orren’s engine could no longer promise a painless life. Its dismantled resonators hung in Ashford’s entrance hall beside the removal orders. Elara kept the emerald seal on her workbench as a reminder that a welcome and a claim were different things. She had found her mother. More importantly, they could now choose what kind of family they would become.`]
];

const seaSettings=[place('sea-port','Brinehaven','Harbour city','/images/sea.jpg','A tidal city built on rusting stilts. A vast clock predicts the tide, and every family carries a brass flood token. Its lower wards flood first while wealthy terraces are protected by privately owned pumps.','Salt-stung · Mechanical · Divided','Exterior · Storm season'),place('sea-engine','The Pelagic Engine','Industrial heart','/images/library.jpg','A submerged turbine chamber beneath the harbour clock. Tide records reveal that the engine is not predicting water but quietly holding it away from the upper city.','Claustrophobic · Deafening · Corroded','Interior · Below sea level'),place('sea-island','Bellwether Island','Final refuge','/images/sea.jpg','A derelict weather station on a granite island. Its cable can transmit the city’s last warning, but the settlement has only enough dry ground for those who arrive before the storm front.','Exposed · Communal · Fragile','Exterior / Interior · Night')];
const seaCast=[{id:'nima-oss',name:'Nima Oss',age:31,role:'Protagonist',description:'A harbour clock mechanic who learned to read tides from her missing father’s notebooks. Nima trusts measurable systems and regards civic politics as a distraction until the numbers prove someone is purchasing safety with other people’s homes.',desire:'Find her father and expose the false tide predictions.',conflict:'Her faith in technical solutions collides with a problem caused by ownership rather than faulty engineering.'},{id:'tavi-reed',name:'Tavi Reed',age:19,role:'Ally',description:'A courier from the lower wards who memorises escape routes and delivers medicines by skiff. Quick to joke, he keeps a list of neighbours who cannot climb. His practical courage challenges Nima’s habit of waiting for complete information.',desire:'Get his mother and the ward’s housebound residents to higher ground.',conflict:'Leaving early would protect his family but abandon people who depend on him.'},{id:'sena-oss',name:'Sena Oss',age:63,role:'Missing engineer',description:'Nima’s father, detained after discovering the tide engine’s true operation. He designed its first regulators but refused to certify its privately sold safety margins. Years of captivity have made him cautious without making him obedient.',desire:'Stop the engine before its concealed pressure fractures the harbour wall.',conflict:'He wants to protect Nima from the consequences of a truth he taught her to pursue.'},{id:'councillor-vane',name:'Ilyan Vane',age:52,role:'Antagonist',description:'A shipping magnate elected to manage the city’s flood authority. Vane sincerely believes profitable trade keeps Brinehaven alive and therefore treats wealthy districts as infrastructure worth saving first.',desire:'Preserve the upper port and the authority’s solvency.',conflict:'His definition of survival excludes the people who do the surviving.'}];
const seaChapters=[
['A clock six minutes late',0,`Nima heard the harbour bell after the water had already crossed the medicine dock. The clock had never been late in thirty years. She climbed its maintenance stair and found fresh tool marks beneath a regulator she alone was authorised to open. Inside lay a scrap of her father’s handwriting: Measure the water, not the promise.

Sena Oss had vanished eight months earlier. The flood authority said he had sailed south with a research crew, but no southbound ship carried his name. Nima had searched the departure books until grief became another routine she could perform without thinking.

At the dock, Tavi hauled his mother’s medicine out of knee-deep water. He showed Nima two flood tokens issued on the same day, one accurate and one almost an hour wrong. Someone was giving different warnings to different wards. A storm front was due before midnight. Nima could question the authority’s chief timekeeper or follow the new service cable descending from the clock into the harbour.`],
['The respectable lie',0,`The chief timekeeper showed Nima a ledger whose totals were immaculate. Every adjustment had a councillor’s seal. Vane had ordered a “commercial correction” to protect incoming cargo from panic, and the lower wards had received their warnings after the upper terraces closed their gates.

Nima asked for the raw measurements. The timekeeper lowered his voice and opened a drawer containing Sena’s last report. Its pages described a pressure curve, not a tidal prediction. “Your father wouldn’t sign the correction,” he said. “They told us he was unwell.”

Tavi arrived at the window with a warning: authority patrols were checking the mechanics’ workshops. The timekeeper gave Nima his personal exit token and stayed behind to ring the bell manually. Before they left, she copied every seal in the ledger. Whatever they found beneath the clock, the record would show that the city’s failure had been a decision.`],
['Under the waterline',1,`The service cable led to a maintenance hatch hidden behind a buoy store. Nima and Tavi descended into a chamber where seawater trembled against glass as thick as a door. A turbine turned inside the wall, drawing power from the upper port and displacing water towards the lower wards.

Sena’s handwriting covered a chart beside the pressure gauge. The newest notes were dated that morning. Nima pressed her fingers against the ink and had to stop herself from shouting his name. Somewhere inside this mechanism, her father was still working.

An authority engineer found them and reached for an alarm. Tavi held up his mother’s ruined medicine packet and asked which part of the engine kept her safe. The engineer looked at the rising gauge, then unlocked an inner door. “It doesn’t,” she said. She led them towards the holding room before she could change her mind.`],
['The man behind the gauge',1,`Sena was alive, thin, and furious when Nima called him a prisoner. Vane had offered him release every week on condition that he certified the engine. He had stayed because an inexperienced replacement would have burst the harbour wall months ago.

The machine could delay flooding but not remove water. Each profitable week stored pressure beneath the seawall. Tonight’s storm would push it beyond tolerance. Shutting it down immediately would send a controlled surge through the lower wards; leaving it running would destroy the port and everyone inside it.

Nima wanted a third equation. Sena let her search his calculations until she found the blank space where he had already tried. Tavi asked a more useful question: how long before the worst surge? Forty minutes. His list of neighbours would take longer to evacuate unless the upper gates opened. They took Sena’s pressure records and climbed to the council chamber.`],
['The gates at Mariner’s Rise',0,`Vane listened to the gauge readings and ordered the upper gates sealed. He offered Nima a place for her family on the last authority launch. “You cannot save a city by destroying its only functioning district,” he said.

Tavi threw his flood token onto the council table. The brass disc still carried Vane’s promise of equal warning. Nima placed the copied ledger beside it and sent the pressure records through the public speaking tubes. Shopkeepers in the upper streets heard their own paid protection described as a transfer of danger to their workers’ homes.

People began opening gates from inside. Some did it angrily, some apologetically, and many only because their families lived below. Vane ordered the speaking tubes cut, but the warning had spread. Sena stayed at the engine to slow the pressure rise. Nima took charge of a city that had discovered it could act without waiting to be invited.`],
['A choice the sea will keep',0,`The first evacuation boats returned overloaded. Tavi’s list had become a wet ledger of names and addresses. Most residents were climbing towards Mariner’s Rise, but Bellwether Island held the only long-range transmitter, and its weather mast was beginning to buckle.

Nima had two workable plans. She could shut the engine down gradually and use the city’s remaining power to run the upper flood pumps. It would save Brinehaven’s inhabited streets, but a trapped research fleet beyond the harbour would not receive a warning in time. Or she could divert that power to the island cable, warn the fleet, and open the emergency seawall channels. The lower city would be lost while the evacuated population sheltered on the terraces and island.

Sena refused to choose for her. Tavi named the remaining people in danger instead of counting them. Nima checked the tide one last time. Whatever she chose, she would publish the calculation and the names afterwards.`],
['The controlled surge',1,`Nima turned the intake wheels by hand while Sena watched the pressure needles. Above them, the upper pumps roared into service. Water entered the lower wards street by street instead of arriving as a wall. Tavi guided the last skiffs through gaps marked with lanterns.

The island transmitter went dark. Nima wrote the research fleet’s call signs on the back of her hand so she would not let relief turn them into an abstraction. A fishing captain offered to carry a visual warning beyond the harbour. It was late, but she authorised every available signal lamp and sent him with volunteers who understood the risk.

When the final valve closed, Sena collapsed against the gauge. Nima held his shoulders until he could breathe normally. They had saved the inhabited city, not solved the storm. Dawn would bring a reckoning with both the authority’s choices and their own.`],
['The city that opened itself',2,`Nima diverted the power and the island mast flared across the water. The research fleet acknowledged the warning just before the cable burned through. Below Brinehaven, the emergency channels opened and the sea reclaimed streets it had been forced to carry elsewhere.

Tavi stood at the upper gate reading names as each evacuation boat arrived. Sena emerged on the last maintenance skiff with the chief timekeeper and three engineers. Nima watched her workshop disappear through the spray. Her tools, her father’s first clock, and the room in which she had learned her craft were gone.

On Bellwether, the research crews began transmitting their own weather data back towards the mainland. They sent dry clothes, spare radios, and the promise of supply ships. Survival had become a network of obligations rather than a privilege purchased from a council. Nima sat beside Tavi’s mother and let herself mourn the workshop without calling the decision a mistake.`],
['A public clock',0,`Six weeks later, the harbour bell rang from a temporary tower built with salvaged beams. Nima refused a councillor’s title and accepted a maintenance contract that required every tide reading to be public. Sena trained apprentices from both sides of Mariner’s Rise. The authority’s private seals were removed from the warning tokens.

The fishing captain returned with two research vessels. One had lost its engines during the storm; the other had stayed to tow it. There were injured crew, damaged equipment, and a difficult record of decisions to examine, but every ship was accounted for. Nima took the call signs off her hand and entered them into the city archive.

Vane stood trial on the ledgers he had signed. Tavi became the flood ward’s elected coordinator and kept the list of neighbours who needed help climbing. On the repaired clock face, Nima engraved her father’s instruction. The city would still face storms. It would no longer be told the sea kept different time for different people.`],
['The harbour of everyone',2,`Brinehaven’s lower streets remained underwater. Reconstruction began on the terraces under rules that reserved homes for those displaced by the authority’s engine. There were arguments about land, money, and the names of streets no longer visible. Nima refused every suggestion that gratitude should make those arguments disappear.

The research fleet returned with floating workshops and a public weather service. Sena built a small clock for the new assembly hall. It displayed the tide itself, including uncertainty, rather than an authority’s promise. Tavi’s mother planted medicinal herbs in roof beds along the evacuation route.

At the engine’s hearing, Vane described the lost district as an unavoidable sacrifice. Nima placed the evacuation ledger on the witness table and read the names of the people his policies had repeatedly put at risk. Then she described her own decision without euphemism. The new city had no machine capable of making the sea harmless. It had citizens who could hear the same warning and decide together what to do.`]
];

const orchardSettings=[place('orchard-glass','The Glass Orchard','Agricultural sanctuary','/images/forest.jpg','Terraced trees carry transparent fruit containing preserved sensory memories. Every harvest is sold to people who can no longer remember a loved one. Pollination depends on a small wild grove the company has marked for removal.','Luminous · Fertile · Controlled','Exterior · Early summer'),place('orchard-lab','House of Germination','Research complex','/images/library.jpg','A sealed botanical laboratory beneath the terraces. Root samples show that the orchard is copying living memory from nearby residents rather than manufacturing it.','Sterile · Root-bound · Secretive','Interior · Day'),place('orchard-river','The Open River','Recovery landscape','/images/sea.jpg','An irrigation river lined with family gardens. Its free-growing trees carry imperfect fruit with no marketable guarantees, but do not extract memory from anyone.','Imperfect · Abundant · Shared','Exterior · Dawn')];
const orchardCast=[{id:'iris-quell',name:'Iris Quell',age:34,role:'Protagonist',description:'A graft specialist returning home after her brother’s death. Iris can identify a tree by the shape of a scar in its bark. She has bought one memory fruit and is ashamed that hearing her brother’s voice matters more to her than asking who paid for it.',desire:'Understand why her brother’s final harvest failed.',conflict:'The discovery that preserves his voice also perpetuates the harm he died trying to stop.'},{id:'orin-quell',name:'Orin Quell',age:29,role:'Absent catalyst',description:'Iris’s late brother, an irrigation engineer who recorded evidence inside unsold fruit. Remembered as reckless by his employer, he was quietly careful with the orchard’s oldest trees.',desire:'Leave evidence that someone he trusts can understand.',conflict:'He could expose the theft only by working inside the system long enough to become implicated in it.'},{id:'petra-moss',name:'Petra Moss',age:67,role:'Ally',description:'A local nursery owner whose memories of her husband are vanishing. Petra tracks losses on paper and refuses to let others treat her as a collection of symptoms. Her garden preserves the wild species the orchard has replaced.',desire:'Keep the right to decide which memories and plants are worth preserving.',conflict:'She needs care from neighbours while fighting the industry that employs them.'},{id:'director-cairn',name:'Leonie Cairn',age:48,role:'Antagonist',description:'Director of the orchard cooperative after converting it into a private biotech company. Cairn built a business offering relief from grief and cannot bear to acknowledge that its raw material is stolen.',desire:'Complete the export harvest before the root network is discovered.',conflict:'Her genuine belief in the comfort of the product has become an excuse not to examine its source.'}];
const orchardChapters=[
['The voice inside the fruit',0,`Iris opened her brother’s final parcel at the kitchen table. The glass fruit inside was cloudy, commercially worthless, and shaped by an old graft she recognised from childhood. When she cut its skin, she heard Orin saying that the river pump had been turned backwards.

The official account of his death described a fall during routine maintenance. His employer had paid for the funeral and sent Iris a polished fruit containing his laughter. She had listened to it every evening for a week. This damaged specimen held a different voice: tired, specific, and interrupted by machinery.

Outside, Petra Moss struggled to remember which key opened the garden gate she had used for forty years. Iris wrote the day’s incident in Petra’s notebook and saw that such losses had increased with the summer harvest. She could inspect Orin’s irrigation station or begin with the old graft hidden at the centre of the orchard.`],
['Water running uphill',1,`The pump station drew river water into the orchard at night and returned it through the town’s garden channels before dawn. Orin’s maintenance marks revealed a second flow: a fine network of roots running upstream inside the pipes. Iris followed it to a filter labelled Sensory stabilisation.

Inside the filter lay fibres from trees planted in residents’ gardens. Each bore the same legal tag as the company’s licensed fruit. Someone had used the public irrigation network to connect private memories to the orchard’s harvest.

A young technician admitted Orin had ordered a shutdown. Director Cairn had reversed it and sent him into the pressure tunnel alone. The technician gave Iris a copy of the order, then asked whether exposing it would close the nursery where her mother worked. Iris said she did not know. It was the first honest answer anyone had offered the technician all week.`],
['The tree that would not forget',0,`At the orchard’s centre, Iris found the tree she and Orin had grafted as children. Its fruit contained only their own memories because its roots had never joined the irrigation pipes. Orin had concealed a recording in the branch where Iris once carved her initials.

He explained that the orchard’s commercial certainty was impossible. A tree could preserve a freely given memory, imperfectly, or extract exact copies from living people connected to its roots. Cairn had chosen extraction and concealed the losses as a regional illness.

Iris touched the cloudy fruit in her pocket. Orin had deliberately used an imperfect recording because it could not take anything from her. Petra arrived carrying a nursery ledger. The first affected gardens belonged to families who had refused to sell their land. They carried the ledger and recording to the House of Germination, where the harvest was already being packed for export.`],
['A harvest of other people',1,`The laboratory held samples from hundreds of residents, coded by address. Researchers had mapped which memories sold best: voices, holidays, the texture of being held. Iris found Petra’s husband listed as a high-value recurring source.

Cairn met her beside a refrigerated crate. She did not deny the extraction. She argued that the fruit helped many more people than it harmed and that the losses could eventually be restored. The restoration protocol, however, required destroying the fruit that had already been sold.

Iris held the polished fruit containing her brother’s laughter. She wanted to ask whether this one could be exempted and hated herself for the impulse. Petra read the protocol without offering comfort. “If you need a little time to do the right thing,” she said, “take it. Just don’t call the time a scientific uncertainty.” They copied the source records before Cairn’s security team arrived.`],
['The orchard closes its gates',0,`Cairn suspended harvesting and announced an attack on the company’s research. Growers feared the loss of their contracts. Families gathered outside the laboratory demanding the fruit that contained their own lives. Iris and Petra were caught between people who needed the same wrong to end for different reasons.

The roots began to contract as refrigeration failed. Memories trapped in the ripe fruit were fragmenting. Orin’s shutdown plan offered a way to dissolve the commercial harvest into the irrigation network, returning what could be returned, but it would destroy years of preserved recordings.

Iris played her brother’s laughter once more and then broke the polished fruit over the root inlet. The sound stopped. She was not healed by the gesture. She simply knew she could no longer ask Petra to pay for it. The growers opened the gates, and together they carried the export crates back towards the trees.`],
['What a garden owes',1,`The root network could survive in two forms. Iris could sever the commercial grafts and return the extracted memories immediately, killing the orchard’s productive trees and leaving the town without its main income. Or she could retain a small, closely monitored network while volunteers returned each harvest batch to its sources. That path would preserve more trees but require months of work and expose volunteers to incomplete memories of strangers.

Petra insisted that the affected families choose with the growers, rather than leaving the decision to Iris or a director. Cairn offered to fund either plan if the cooperative withheld the evidence against her. Nobody accepted the condition.

The assembly reviewed the restoration limits aloud. Some losses might be permanent. Some fruit was already overseas. Iris finally understood her brother’s records as an invitation to collective work, not a perfect answer left by a dead man. She stood ready at the valves when the vote was called.`],
['The trees fall silent',0,`Iris cut the last commercial graft while growers opened the river channels. The trees shed their glass fruit, which dissolved into clear water around their roots. Across town, people stopped in the middle of ordinary tasks as fragments of lost days returned.

Petra remembered her husband’s habit of leaving a second cup beside the kettle. She also remembered a quarrel she had not missed. Recovery restored complexity rather than a comforting performance. Iris stayed with her while the orchard’s upper terraces darkened.

By evening, the productive trees were dead. The growers stood among trunks that represented mortgages, apprenticeships, and futures they had expected to hand their children. Iris did not call the loss beautiful. She pledged her savings and the laboratory’s seized equipment to a public nursery. Petra brought the wild seedlings she had refused to surrender.`],
['A slower kind of repair',1,`The restoration team labelled each batch with a source address, a consent record, and an uncertainty note. Iris trained the growers to recognise when a root had begun extracting instead of returning. They stopped work every time it happened, even when deadlines slipped and buyers threatened to sue.

Cairn’s accounts funded the work under a court order. Petra chaired the residents’ review circle and made sure no specialist could speak over a person describing their own memory. Volunteers sometimes came home carrying unfamiliar sensations: a stranger’s wedding music, fear in an unknown corridor. The programme paid for rest, counselling, and time away.

Iris preserved the childhood graft at the orchard’s centre as a control specimen. Its cloudy fruit remained freely given and unreliable. For the first time in years, a product that could not guarantee relief was allowed to exist without being improved into something cruel.`],
['The first ordinary harvest',2,`A year later, Iris carried a basket of actual pears through the old export gate. The new nursery supplied flood-resistant seedlings and grafting courses. Income was modest and distributed openly. Some families moved away, and the cooperative paid the relocation costs from the company’s recovered funds.

Petra’s garden became a place where neighbours wrote down what they remembered together. There were gaps nobody could fill. Iris no longer replayed her brother’s laughter, but she began remembering unexpected things about him without a device: his impatience with blunt knives, his terrible singing, the time he stayed up all night fixing her first graft.

At the inquiry, Orin’s damaged recording established that he had been sent into an unsafe tunnel after reporting the theft. The ruling could not restore him. It could name what had happened. Iris planted a wild pear by the river and left its fruit for whoever needed it. Nothing in the tree required a person to become less themselves.`],
['A memory freely given',2,`The final restoration batch returned in autumn. Iris shut the licensed root network down and let the growers inspect every disconnected pipe. Most trees survived, but the company’s famous exactness did not. The orchard reopened as a public research garden that accepted donated recordings only.

Petra contributed a memory of her husband teaching a neighbour to prune. It held the rhythm of his instructions but not a perfect voice. She approved that imperfection. A visitor could encounter him without possessing him.

Iris made a recording about Orin that included both love and anger. She described the risks he took, the evidence he left, and the sister who had needed time before believing him. Cairn’s name remained on the public responsibility register beside the compensation orders. At closing, Iris returned to her childhood tree and tasted a cloudy fruit. It gave her a fragment of sunshine and nothing she had not chosen to offer. For once, that was enough.`]
];

const europaSettings=[place('europa-station','Aster Station','Orbital habitat','/images/space.jpg','An ageing research habitat above Europa. Windows face a world nobody is authorised to enter. The station’s life support can sustain the crew or a contaminated rescue capsule, not both indefinitely.','Precise · Isolated · Deteriorating','Interior · Orbital night'),place('europa-ice','The Blue Fissure','Contact zone','/images/sea.jpg','A fracture in the moon’s ice where a probe records patterns that respond to human timing. Pressure, radiation exposure, and limited communications make every delay a physical decision.','Vast · Unfamiliar · Responsive','Exterior · Subsurface expedition'),place('europa-relay','Relay Nine','Emergency outpost','/images/space.jpg','A decommissioned communications platform with an independent air loop. It can hold an isolated crew for several weeks if someone repairs its cracked thermal shield.','Silent · Improvised · Hopeful','Interior / Exterior · Deep space')];
const europaCast=[{id:'dr-ada-sen',name:'Dr Ada Sen',age:39,role:'Protagonist',description:'A xenobiologist responsible for Aster’s sterile-contact protocols. Ada wrote the rule that no rescue should contaminate a possible ecosystem. Her former partner is aboard the capsule that now tests whether she can apply her own principle without becoming inhuman.',desire:'Bring the rescue crew home without destroying evidence of nonhuman life.',conflict:'Scientific caution becomes emotionally intolerable when the person waiting for air has a familiar voice.'},{id:'noah-voss',name:'Noah Voss',age:41,role:'Stranded explorer',description:'A pilot who chose a dangerous ice survey after his relationship with Ada ended. Noah communicates in practical observations rather than reassurance and refuses to let his need for rescue stand in for consent from the ecosystem.',desire:'Keep his two crewmates alive and preserve the contact recordings.',conflict:'He must ask for help without asking Ada to abandon the ethics they once shared.'},{id:'mei-okoro',name:'Mei Okoro',age:27,role:'Systems engineer',description:'The youngest engineer on Aster and the person most familiar with the station’s unofficial repairs. Mei understands hardware as a history of compromises. Her proposal to revive Relay Nine makes a third form of responsibility imaginable.',desire:'Turn institutional risk limits into a workable rescue design.',conflict:'She has to challenge senior scientists without understating the danger of her own plan.'},{id:'captain-reyes',name:'Captain Tomas Reyes',age:54,role:'Commander',description:'A career mission commander with a strict duty to the unexposed crew. Reyes initially treats quarantine as a binary choice, then learns that leadership includes making time for a proposal he did not invent.',desire:'Return all personnel safely while maintaining mission containment.',conflict:'Decisiveness can protect a crew or prematurely close its best options.'}];
const europaChapters=[
['The voice below the ice',0,`The distress call arrived during Aster’s scheduled silence. Noah’s capsule had surfaced through a blue fissure with two injured crew and a sample chamber that would not sterilise. He asked for docking clearance before asking whether Ada was on duty.

Ada recognised the tapping beneath his voice. It matched the delay sequence she had sent to Europa’s ocean through a probe six hours earlier. The sample was responding, or something aboard the capsule was repeating a coincidence with impossible precision.

Captain Reyes ordered the external airlock closed. Quarantine rules required a complete sterilisation cycle, and the capsule had eighteen hours of oxygen. Ada had written that rule after an Earth laboratory accident injured a colleague. Now Noah waited on its other side. She could analyse the responding sample first or examine the capsule’s failed sterilisation system for a safe way to bring its crew inside.`],
['A reply, not an echo',1,`Ada sent a prime-number sequence through the probe and asked Noah to keep the capsule’s transmitters silent. The sample responded with a sequence of its own, then changed it after she introduced a deliberate error. The patterns were not proof of intelligence, but they were enough to make destruction an irreversible scientific and ethical choice.

Noah described a filament growing across the sample chamber’s thermal grid. It contracted when the lights brightened and restored the pressure seal around a fractured window. Something was interacting with the machine as an environment rather than simply surviving inside it.

Ada recorded uncertainty carefully. She did not label the filament a person, and she did not let uncertainty become permission to kill it. Mei listened to the thermal data and recognised a cycle used by an older habitat design. Relay Nine, long abandoned, still had an independent life-support loop. The failed rescue might be a problem of location rather than impossible compatibility.`],
['The fault that was not a fault',0,`Mei replayed the capsule’s sterilisation logs while Ada examined its air chemistry. Each time the system heated the sample chamber, pressure rose near the injured crew’s cabin. The filament had grown around a damaged exchanger and was holding a crack closed. Successful sterilisation would destroy the only temporary seal between the crew and vacuum.

Reyes demanded a reliable repair estimate. Mei gave him a range instead, including the possibility that no repair could be made from inside. Ada asked Noah for permission to use the capsule’s external maintenance camera. His crewmate Lin held the camera steady with a splinted arm.

The footage showed anchor points compatible with Relay Nine’s unused docking collar. Mei found the outpost’s archived plans and overlaid their remaining fuel margins. They could reach it. They could not rely on its air until someone inspected the platform in person. Ada volunteered before Reyes had finished asking who understood the contamination risks.`],
['The shape of a third option',2,`Relay Nine was dark except for a maintenance beacon blinking every forty seconds. Ada and Mei entered through a cold docking tunnel and found frost across the interior handrails. The air loop had power, but a cracked thermal shield would expose everyone inside to dangerous temperature swings within two orbits.

Mei proposed using the rescue capsule’s surviving shield as a patch. That would leave Noah’s vehicle unable to return independently, but allow an isolated habitat to support both crew and sample until a properly equipped ship arrived.

Ada called Aster and laid out every limit: uncertain biological containment, a repair that required a suited worker outside the station, and a longer mission than their contracts covered. Reyes asked whether she was recommending it because Noah was aboard. She said yes, in part, and also because there were two other people there and a possibly living system they had not understood. Honesty was not a disqualification for judgement.`],
['The consent of the people at risk',0,`Reyes opened a recorded conference with both crews. Ada explained the evidence without calling the filament friendly. Mei described the shield patch and what would happen if it failed. Noah’s injured crewmates asked about pain medication, recovery time, and whether rescue at Relay Nine meant permanent abandonment.

The supply ship could arrive in twenty-three days. Isolation would last at least that long, perhaps longer. Everyone exposed would retain the right to request return if Earth authorities later approved a different protocol. Aster’s unexposed crew would not be asked to accept an uncontrolled air transfer.

For the first time, the plan sounded like people organising a risk rather than institutions protecting a category. The crews agreed to approach Relay Nine. As the capsule aligned with the collar, the filament brightened in a pattern matching the outpost beacon. Ada recorded the observation and refused to pretend she knew what it meant.`],
['The last clean air canister',2,`The docking impact widened the shield crack. Mei could patch it in a suit using the last uncontaminated air canister, leaving Ada to manage the interior contact protocol alone. Or Ada could perform the external repair while Mei remained inside to disconnect the sample chamber if the filament crossed into the crew cabin.

The choice changed who would carry the immediate risk. Ada had the stronger suit training but was also the only specialist able to interpret the biological responses. Mei could make the repair more quickly, though her damaged glove regulator would reduce her reserve margin.

Noah offered to go out despite his injuries. Both women refused the proposal for specific physical reasons rather than a claim to heroism. Reyes authorised either plan after hearing the calculations. Ada checked Mei’s glove personally. They had six minutes before the station rotated into shadow. The mission now depended on which competence they were prepared to trust with what they could not replace.`],
['The engineer in the dark',2,`Mei crossed the hull with the shield patch tethered behind her. Inside, Ada dimmed the sample chamber as its pressure began climbing. The filament responded to the change by withdrawing from the maintenance seal, then regrowing along a cooler surface. Ada found a narrow thermal range in which it maintained the crack without spreading.

Outside, Mei’s glove alarm sounded. Ada could hear every breath through the open channel and had to keep her hands steady on the controls. She gave Mei only the measurements that mattered, leaving Reyes to handle reassurance and timing.

The final clamp engaged three seconds before shadow. Mei returned with numb fingers and a repair report containing the words temporary, inspect daily. Ada did not improve the language. Noah’s crew transferred into isolation, and the first pressure test held. Their successful rescue was a beginning of care, not an excuse to stop measuring.`],
['The scientist outside the window',2,`Ada moved across the hull using Mei’s spoken instructions. Through a window she saw Noah holding a light over Lin’s injured arm. She had spent the mission trying to make decisions about a crew from a distance; for a moment she saw only people doing ordinary work to keep one another alive.

The shield patch caught on a damaged rail. Ada freed it with one hand and watched a tool drift away beyond the tether. There was no time to recover it. Mei guided her through the last clamp using an improvised connector taken from the capsule’s cooking unit.

Inside the station, the filament crossed the sample boundary. Mei isolated the chamber exactly as agreed, preserving the sealed section while cutting its connection to the cabin. Ada returned to a stable habitat and a scientist’s difficult relief: they had contained something they might later understand as a response, an accident, or a loss.`],
['Twenty-three days of listening',2,`The supply ship arrived with isolation modules and specialists who had spent the journey studying Ada’s recordings. Mei’s patch had held through every inspection. Her fingers recovered slowly, and the mission funded a treatment plan rather than giving her a medal in place of care.

The filament continued to respond to thermal patterns, though not reliably enough to support grand claims. Ada published the failures with the successes. Independent reviewers would decide what the observations justified. Noah asked whether she regretted choosing Relay Nine. She said she regretted that no one had funded a rescue habitat before they needed one.

They returned separately to Earth quarantine, alive and carrying a long research programme rather than proof of a cosmic revelation. Reyes recommended permanent sterile rescue capacity. In her final log, Ada described the first contact the mission could confidently claim: people had listened to the risks faced by others and built a way home that did not require pretending those risks were simple.`],
['A boundary held with care',2,`The isolated sample section remained at Relay Nine when the supply ship docked. Ada recorded a final pattern through its thermal grid. A response arrived twelve minutes later, too late to establish an exchange before departure. She archived it as unresolved rather than turning it into farewell.

Noah’s crew entered the ship’s containment module. The patch, the severed chamber, and every instruction Mei had followed remained available for independent examination. There would be difficult questions about what had been cut away and whether another method could have preserved more. Ada welcomed them. A rescue was not made ethical by refusing to review it.

Back on Earth, she and Noah met through a quarantine window and spoke without planning a restored relationship. They had saved each other without acquiring a claim on each other’s future. Aster’s mission ended with all crew alive, an intact evidence archive, and a new rescue protocol. Far below the abandoned outpost, the ocean continued its own history without needing a human ending.`]
];

const namesSettings=[place('names-market','The Name Exchange','Civic marketplace','/images/city.jpg','A covered market where citizens rent professional identities. Name tokens open clinics, housing lists, and work permits. Every transaction is legal, and every rented identity leaves someone less able to prove who they are.','Neon-lit · Bureaucratic · Crowded','Interior / Exterior · Rainy evening'),place('names-archive','The Registry Below','State archive','/images/library.jpg','A subterranean record hall where original identities survive beneath layers of licensed aliases. Unclaimed names are scheduled for deletion during an annual database consolidation.','Ordered · Vast · Airless','Interior · Night'),place('names-roof','The Rooftop Assembly','Public meeting place','/images/city.jpg','A laundry roof above the market with a pirate radio antenna and an improvised projection screen. Here, private injuries can become a public record.','Windy · Exposed · Collective','Exterior · Dawn')];
const namesCast=[{id:'mara-vel',name:'Mara Vel',age:26,role:'Protagonist',description:'A courier renting a paramedic’s name to gain access to medicine for her younger sister. Mara can memorise a delivery route after one walk, but has begun forgetting which memories belong to her licensed identities.',desire:'Recover her original legal name before the registry deletes it.',conflict:'Returning every borrowed name may remove the access that keeps her sister alive.'},{id:'joss-vel',name:'Joss Vel',age:16,role:'Family anchor',description:'Mara’s younger sister, an avid amateur radio operator with a chronic lung condition. Joss rejects the idea that being cared for makes her a justification for harming strangers.',desire:'Keep her family together without requiring another person to disappear.',conflict:'She needs medicine while refusing the passive role assigned to her.'},{id:'felix-ren',name:'Felix Ren',age:44,role:'Ally',description:'A former registry auditor whose professional identity was sold after he reported deletion errors. Felix works as a night cleaner in the archive he helped design.',desire:'Make original identities recoverable without turning people into another searchable commodity.',conflict:'His useful technical knowledge is inseparable from his role in building the system.'},{id:'commissioner-saye',name:'Commissioner Leda Saye',age:50,role:'Antagonist',description:'The official who converted civic identity into an efficiency market. Saye can quote improvements in clinic throughput while ignoring people removed from the denominator.',desire:'Complete the consolidation and preserve public confidence.',conflict:'She regards recognition as an administrative resource rather than a condition of equal citizenship.'}];
const namesChapters=[
['A receipt with no customer',0,`Mara delivered a name token to a clinic and waited while its owner signed the receipt. For one impossible moment, her own childhood photograph appeared on the customer screen. Then the system corrected itself and called her by the paramedic’s name she had rented for six months.

At home, Joss could no longer find Mara’s original name on their household record. The registry’s annual consolidation would delete inactive identities at dawn. Mara had twelve hours to prove a life whose documentary traces she had gradually sold for access to work and medicine.

The receipt contained an archive location and an auditor’s code. Mara recognised the code from a stranger who had once tried to warn her about the exchange. She could track the person now using her childhood identity or find the auditor before the registry sealed its night entrance. Joss tuned the radio to an unused civic frequency and told her to keep the channel open.`],
['The woman wearing yesterday',0,`The person using Mara’s name was a retired teacher seeking housing after her own identity had been deleted. She had not stolen it knowingly. The exchange had advertised a clean civic record with full family access, and she had used her savings to buy it.

Mara wanted to be angry at someone within reach. Instead she asked the teacher to describe the sale. Its approval carried Commissioner Saye’s office seal and a timestamp before Mara had supposedly consented to release her original identity.

The teacher offered to surrender the token, but doing so immediately would cancel the temporary home where she was sheltering three children. Mara copied the sale record and asked her to come to the rooftop assembly at dawn. A private correction would simply make another vulnerable person invisible. She needed the registry’s original files, and someone who could explain how its omissions had been made.`],
['The auditor with a broom',1,`Felix Ren cleaned the archive’s polished floors under a name rented from a man who had died overseas. He had designed the system that made original records recoverable, then been removed after documenting that the exchange sold identities without valid consent.

Mara showed him the receipt. He recognised a mirror record, a temporary copy generated before an original name was scheduled for destruction. If they reached its storage sector before dawn, they could establish her identity and expose the deletion queue.

Felix refused her request to print every name. A public dump would reveal medical histories, addresses, and refuge locations to anyone willing to search them. “Recognition is not the same as exposure,” he said. Joss, listening over the radio, asked whether they could publish proof of the system’s decisions without publishing the lives inside it. Felix stopped sweeping. That was a question he knew how to answer.`],
['The lives beneath the aliases',1,`The registry’s original sector held overlapping versions of people the city described as inactive. Mara found clinic visits performed under five borrowed names, her sister’s birth record, and the day their mother registered the family after crossing the northern border.

She also found the people whose identities she had rented. One had lost access to a pension while Mara used the token. Another had been refused a replacement name because his record appeared active. Her emergency had not existed outside the exchange’s harm.

Felix built a proof file containing transaction signatures and deletion counts, with personal details separated into encrypted packets for their owners. Saye’s security service detected the query and offered Mara a private reinstatement in exchange for closing it. Joss interrupted the call from home. “I need medicine,” she said, “but I also need a city where you don’t have to keep buying someone else’s life.” Mara copied the proof file.`],
['The consolidation begins early',1,`Saye moved the deletion forward by two hours and blamed a technical fault. Whole sectors of the registry began closing while Mara and Felix crossed the service levels. The proof file was safe, but encrypted identity packets still needed delivery keys.

Joss directed them using maintenance diagrams broadcast by the former auditor’s colleagues. People who had quietly accepted the exchange’s rules began opening doors and sharing access. The retired teacher arrived at the rooftop with parents, cleaners, and clinic workers who could testify to records that had vanished.

Felix stayed at the central terminal to generate consent-based recovery keys. Mara refused to leave until he showed her a route out and a timed failsafe that would not depend on his survival. They tested both before separating. What they were building had to be more responsible than a plan requiring one guilty man to redeem himself by dying.`],
['To be recognised without being exposed',2,`At the rooftop antenna, Joss prepared two broadcasts. One would publish the proof and distribute encrypted recovery keys through local clinics and legal aid workers. It protected privacy, but Saye might suppress it before every district received a key.

The second would use the registry’s own civic screens to display public transaction signatures and freeze the consolidation through a mass legal challenge. It would reach every district immediately, but Mara and Joss would have to authenticate the challenge with their names, exposing their location to Saye’s officers.

Neither plan required releasing private lives as evidence. The assembly asked who would carry each risk, where copies would go, and how families could decline participation. Mara answered in her own voice for the first time since renting the paramedic’s identity. On the screen, a field waited for her original name. The city had taught her that visibility was a privilege. She was about to make it an accountable decision.`],
['A thousand sealed envelopes',2,`The proof went out over Joss’s transmitter in repeated short packets. Clinic workers printed recovery forms that did not require an existing civic token. Legal aid teams checked each request in person before releasing a decryption key. The process was slower than the exchange’s sleek counters and far harder to buy.

Saye’s officers reached the roof after the first packet had been copied to seven districts. They shut the antenna down, but the proof continued through ordinary phones and clinic printers. Mara and Joss were taken to a holding office where a duty solicitor arrived with their recovery keys already verified.

Felix emerged from the archive through his tested service route, exhausted rather than transformed. He handed himself in as a witness and supplied the signatures linking the deletions to official orders. Mara understood the work ahead would be measured in appointments, not one victorious signal.`],
['The city reads the signature',2,`Mara authenticated the challenge under her birth name. The civic screens paused their advertising and displayed the transaction signatures, consent failures, and legal basis for freezing deletion. Joss transmitted the same proof to independent record keepers before the first screen went dark.

Officers climbed the roof. The assembly did not scatter. People stood beside the sisters holding paper statements with their own names and the names they had been forced to rent. A clinic director offered her professional certification as a witness. The officers had arrived to remove two unlicensed residents and found a public hearing already beginning.

The emergency court froze the consolidation pending review. Mara’s address was now public, and the legal team arranged temporary protection rather than pretending courage removed danger. Joss closed the transmitter only after every district acknowledged receiving the proof. Below them, the Name Exchange stopped selling tokens for the first time anyone could remember.`],
['The work of returning',0,`Identity recovery took the winter. Some cases required testimony from neighbours because the registry had already destroyed its originals. The court funded that work from the exchange’s assets and barred recovery providers from selling the records they helped restore.

Mara returned the paramedic’s token with a signed account of its use. The original owner recovered his pension and asked her to help deliver medicines under her own courier licence. Their first conversation was uncomfortable, and neither tried to improve it with a claim that necessity made everything harmless.

Joss’s treatment moved to a clinic authorised to serve people before verifying an identity. Felix testified about both the system’s safeguards and the decisions that disabled them. Saye lost her office and faced a public trial. In spring, Mara signed a delivery receipt with a name she no longer needed to rent. The signature opened no secret door. It meant that the person who had done the work could finally be paid for it.`],
['A name spoken in daylight',2,`The final hearing took place on the same roof where the assembly had blocked the officers. Mara read the new civic guarantee: nobody would lose emergency care, a home address, or the right to challenge a record because their name was missing from a database.

The guarantee required funding and enforcement, and the assembly elected a review group to monitor both. Joss joined as its youngest radio operator, responsible for reaching people unable to attend in person. Felix worked on a public recovery tool whose code and access rules were independently audited. He was not allowed to administer it alone.

Mara met the retired teacher outside the former exchange. Both now had valid records, and neither needed to surrender shelter for the other to exist. On the city screen, the last deletion notice was replaced by information about recovery appointments. Mara took Joss’s hand and said their family name aloud. For once, the system had to make room for the people who were already there.`]
];

const emberSettings=[place('ember-desert','The Ember March','Crossing landscape','/images/desert.jpg','A desert crossed by migrating settlements. Its maps describe water rights as carefully as geography. A newly uncovered route could connect the wells, but publishing it without consent would expose communities to prospectors.','Severe · Open · Inhabited','Exterior · Dry season'),place('ember-vault','The Cartographer’s Vault','Hidden archive','/images/library.jpg','A buried observatory containing route records made by the families who maintained desert wells. The imperial atlas has erased their names and converted stewardship into supposedly empty territory.','Ancient · Exact · Contested','Interior · Noon'),place('ember-well','The Council of Wells','Civic destination','/images/desert.jpg','A ring of underground reservoirs shared by travelling communities. Its council convenes at night so guards, herders, and children can all attend before departure.','Hospitable · Pragmatic · Collective','Exterior / Interior · Night')];
const emberCast=[{id:'safi-idris',name:'Safi Idris',age:33,role:'Protagonist',description:'An imperial cartographer raised in a travelling well-keeping community. Safi believed an accurate map could protect people until discovering that her employer uses accuracy to make extraction cheaper.',desire:'Deliver her missing mother’s route atlas to the communities named inside it.',conflict:'The professional recognition she earned depends on the institution that erased her family’s stewardship.'},{id:'kellan-ro',name:'Kellan Ro',age:37,role:'Ally',description:'A supply caravan captain with debts to both the empire and the well council. Kellan’s quiet competence includes knowing when a contract has become an instruction to abandon someone.',desire:'Get his convoy and its passengers through the dry season without selling out their route.',conflict:'Repaying a lawful debt could enable a profoundly unjust claim.'},{id:'amina-idris',name:'Amina Idris',age:61,role:'Knowledge keeper',description:'Safi’s mother, presumed dead after refusing to surrender the location of a communal reservoir. Amina has preserved route knowledge through songs, maintenance records, and shared teaching rather than a single secret map.',desire:'Make the atlas useful without allowing it to become a weapon of ownership.',conflict:'She has protected her daughter through silence, at the cost of letting an institution tell their history.'},{id:'marshal-vey',name:'Marshal Cassian Vey',age:49,role:'Antagonist',description:'An imperial survey commissioner who treats unregistered stewardship as absence. Vey remains courteous while ordering legal notices placed on wells whose keepers cannot attend the distant courts that issued them.',desire:'Register the Council of Wells as an imperial concession.',conflict:'His authority depends on describing inhabited land as vacant.'}];
const emberChapters=[
['A blank space with a name',0,`Safi’s new survey showed a reservoir where the imperial atlas printed empty sand. Beside the depth readings, an older hand had written the well’s family name in the language her mother used when tired. Amina had supposedly died crossing this region eleven years earlier.

The survey commissioner ordered Safi to remove the annotation before publication. The reservoir, he explained, would become an imperial concession once its location was confirmed. Safi asked who maintained it. He answered with a legal definition of unregistered land.

That evening, caravan captain Kellan Ro brought her a sealed notebook recovered from a buried waystation. Its opening page bore Amina’s name and instructions to deliver the complete atlas to the Council of Wells. The notebook also described a safe route past a military survey camp. Safi could follow that route immediately or inspect the camp’s sealed excavation records for evidence of what had happened to her mother.`],
['The convoy beyond the markers',0,`Kellan’s convoy travelled before dawn, following stone markers that did not appear on Safi’s employer’s map. At the first well, a teenager recorded each vessel drawn and inspected the shade cloth above the pump. The place was neither abandoned nor untouched. It was maintained through patient, organised work.

Safi showed the notebook to the keeper. He recognised Amina’s handwriting and asked why her daughter wore an imperial survey badge. Safi could not answer without describing the ambition that had made the badge feel like proof she had escaped precarity.

The keeper gave them water under the same ration as everyone else and directed them to the buried observatory. Amina had left teaching records there before the survey troops arrived. Kellan removed the empire’s route seal from his wagon. Safi kept her badge, intending to use its access one final time and then explain exactly what she had done with it.`],
['The sealed excavation',1,`The military camp’s excavation files recorded a noncompliant settlement beside a reservoir. Its residents had been relocated for survey security, then omitted from the concession map because none remained in occupation. Amina’s refusal to sign the clearance order appeared in a witness appendix.

Safi copied the appendix and found evidence that she had been alive when transferred to a medical caravan. The files did not establish where she went next. They did establish that an official story of death had protected a claim to land.

Marshal Vey intercepted Safi at the gate and offered to open an internal investigation after the new map was registered. She asked for the well keepers to attend. He called that an unnecessary complication. Kellan brought the caravan close enough for her to leave the camp among its supply wagons. The copied records rode beneath a sack of salt towards the observatory.`],
['The atlas beneath the earth',1,`The cartographer’s vault held route plates, well-maintenance accounts, and songs notated for learners who travelled without paper. Each described the same country through a different kind of responsibility. Safi found the reservoir she had charted beside generations of repairs paid for in labour rather than imperial currency.

Amina had not hidden one master map. She had distributed essential parts among the communities that kept the water usable. The notebook in Safi’s hands was an index, dangerous only when separated from the people entitled to interpret it.

An old medical log identified Amina’s destination as the Council of Wells. She was alive when the caravan arrived, and the council’s later messages used her teaching signature. Safi cried with relief, then returned to photographing the evidence. Kellan waited until she asked him to help. By sunset they had enough records to contest the concession, but not enough water to reach the council by the usual route.`],
['The price of the shorter road',0,`The route notebook offered a crossing through a narrow basin controlled by the empire. Kellan’s debt contract allowed his cargo through, but not unregistered passengers. Half the convoy consisted of well-keeping families displaced from the very reservoir Safi’s survey would expose.

Marshal Vey offered to forgive the debt if Safi surrendered the atlas. The families would receive escorted passage to a registration camp. Safi had read enough relocation files to recognise how little that promise guaranteed.

The convoy council chose the longer crossing and pooled its water, with extra rations for children and those already ill. Safi contributed the imperial reserve tank attached to her survey vehicle. Its seal broke with an embarrassingly small sound. She logged the use under her own name so that no driver or porter would later be accused of theft. They entered the basin at night, carrying less certainty and a better account of whom they had chosen to protect.`],
['A map is a set of permissions',2,`Amina met the convoy outside the council’s night assembly. Safi embraced her mother before either could prepare a speech about the lost years. Later, when they could speak steadily, Amina explained that she had stayed beyond imperial records because appearing would have exposed the families sheltering her.

The atlas could now support two strategies. The council could release a public map showing the wells as occupied and legally maintained, forcing the concession dispute into open view. Or it could publish the signed evidence of forced relocation while keeping precise routes under community-controlled access until legal protection existed.

The public map might attract international support quickly, but also prospectors. Restricted routes would protect vulnerable wells, but leave distant sympathisers with a less immediately legible story. Safi explained the trade-off rather than recommending the option that would make her work famous. The council heard from every affected keeper before asking her to prepare the chosen edition.`],
['The atlas that named its keepers',2,`Safi replaced the empire’s empty spaces with names, maintenance histories, and access conditions approved by the council. Sensitive seasonal wells remained approximate even in the public edition. The atlas made clear that finding water did not grant permission to take it.

Kellan carried copies to coastal legal offices and published his own debt contract beside the concession papers. The evidence made it difficult to describe the dispute as a romantic objection to development. These were communities with records, infrastructure, and a history of being deliberately excluded from registration.

Vey tried to confiscate the printing plates. A delegation of well keepers met his officers with certified copies already lodged elsewhere. Safi gave up her survey badge in front of them, not as proof of innocence but because she would no longer use that authority to speak over its subjects. Amina stood beside her and let her make the statement herself.`],
['Routes held in trust',2,`The council released the relocation orders, witness statements, and maintenance accounts without publishing the vulnerable crossings. Safi built an access register owned by the keepers, with copies held in several settlements so no official or cartographer could monopolise it.

Aid convoys received temporary route permissions after agreeing to local water limits. Lawyers travelled with well representatives rather than asking them to abandon the dry-season work and appear at a distant imperial court. Kellan negotiated a debt hearing on the road, supported by the people he had refused to leave behind.

Vey accused the council of concealing national resources. Amina answered with a question about the difference between a resource and a relationship. Safi supplied the evidence: a well survived because specific people cleared its silt, repaired its walls, and limited their own use. The restricted atlas preserved that chain of responsibility instead of reducing it to a set of useful coordinates.`],
['A country no longer empty',2,`The concession was suspended pending a land hearing. International attention brought both useful support and opportunistic visitors, so the council maintained its access conditions and turned away crews unwilling to follow them. Safi learned that public recognition created work rather than replacing it.

The first ruling recognised the well keepers’ maintenance records as evidence of continuous occupation. It did not settle every claim. It did require the empire to consult the people whose land its maps had described as empty. Kellan’s contract was revised after the forced relocation evidence established that the debt’s terms had been imposed under duress.

Safi stayed through the next maintenance season, clearing silt before she offered to redraw a route. At night Amina taught her a song whose pauses marked the days between wells. Their reunion did not restore the missing years. It gave them time in which to learn one another again. The atlas’s final page credited its many keepers. Safi’s name appeared among them, exactly the right size.`],
['The well beyond the map',0,`By the next dry season, the council’s access register had become a working agreement among caravans, clinics, and settlements. The wells remained off commercial maps while their legal status was heard. People who needed to travel could request a guide without surrendering their names to a concession company.

Safi presented the relocation evidence in court with Amina and the other witnesses. Vey’s authority to register unoccupied territory was suspended after the hearing established that his own clearance operations had manufactured the supposed absence. The ruling funded reparations and an independent survey process led by the keepers.

Afterwards, Safi returned to the well from her first disputed measurement. She corrected its depth reading, recorded the latest wall repair, and left its exact position in the community archive. A map could tell the truth without telling everyone everything. Her mother waited in the shade with two cups of water. For the first time since childhood, Safi arrived without needing to explain why she had been gone.`]
];

